const additionalQuestions = [[0, [["The slope of a velocity–time graph represents:", ["Displacement", "Acceleration", "Mass", "Force"], 1, "The slope is change in velocity divided by change in time."], ["For constant acceleration, v = u + at with u = 4 m/s, a = 2 m/s² and t = 3 s gives:", ["6 m/s", "8 m/s", "10 m/s", "12 m/s"], 2, "v = 4 + 2 × 3 = 10 m/s."]]], [1, [["Newton’s third-law force pair acts on:", ["The same body", "Different bodies", "Only stationary bodies", "Only identical masses"], 1, "The interaction forces act on the two different interacting bodies."], ["Momentum of a 2 kg body moving at 5 m/s is:", ["2.5 kg m/s", "7 kg m/s", "10 kg m/s", "25 kg m/s"], 2, "p = mv = 2 × 5 = 10 kg m/s."]]], [2, [["A resistor carries 2 A across 12 V. Its power is:", ["6 W", "14 W", "24 W", "144 W"], 2, "P = VI = 12 × 2 = 24 W."]]], [3, [["One mole contains approximately how many specified entities?", ["6.022 × 10²³", "6.022 × 10⁻²³", "18", "1000"], 0, "The Avogadro constant is exactly 6.02214076 × 10²³ mol⁻¹."]]], [4, [["An ionic bond is primarily:", ["Electron-pair sharing", "Electrostatic attraction between opposite ions", "Neutron sharing", "Gravity between atoms"], 1, "Oppositely charged ions attract electrostatically."]]], [5, [["A Brønsted–Lowry acid is a:", ["Proton acceptor", "Proton donor", "Neutron donor", "Salt only"], 1, "Acids donate protons; bases accept them."], ["Neutral water at 25 °C has pH approximately:", ["0", "3", "7", "14"], 2, "At 25 °C, equal hydrogen- and hydroxide-ion concentrations give neutral pH near 7."]]], [6, [["Which organelle carries out much aerobic ATP production in eukaryotic cells?", ["Mitochondrion", "Golgi apparatus", "Cell wall", "Nucleolus"], 0, "Mitochondria host the citric acid cycle and oxidative phosphorylation."]]], [7, [["For Aa × Aa, the expected genotype ratio is:", ["3:1", "1:1", "1:2:1", "9:3:3:1"], 2, "The products are AA, Aa, Aa and aa, giving 1:2:1."], ["Under complete dominance, a dominant allele:", ["Must be more common", "Is expressed in a heterozygote", "Is always beneficial", "Cannot occur in a homozygote"], 1, "Dominance describes phenotype expression, not frequency or benefit."]]], [8, [["Light-dependent reactions in chloroplasts occur in the:", ["Stroma only", "Thylakoid membranes", "Nucleus", "Cell wall"], 1, "Thylakoid membranes contain the photosynthetic electron-transport systems."]]]];
